    public function run(): void
    {
        // Cache dosen_id per nama supaya tidak query berulang untuk nama yang sama.
        $dosenIdByNama = Dosen::pluck('id', 'nama');

        $dilewati = [];
        $dibuat = 0;

        foreach ($this->dataJadwal() as $baris) {
            $namaDosen = $baris['dosen_nama'];
            $dosenId = $dosenIdByNama[$namaDosen] ?? null;

            if (!$dosenId) {
                // Dosen belum ada di tabel dosens — jangan asal buat baris dosen baru
                // yang datanya tidak lengkap (nidn/prodi kosong). Catat saja supaya
                // bisa ditambahkan manual dulu, lalu seeder ini dijalankan ulang.
                $dilewati[$namaDosen] = ($dilewati[$namaDosen] ?? 0) + 1;
                continue;
            }

            Jadwal::updateOrCreate(
                [
                    'hari' => $baris['hari'],
                    'jam' => $baris['jam'],
                    'matakuliah' => $baris['matakuliah'],
                    'kelas' => $baris['kelas'],
                    'jurusan' => $baris['jurusan'],
                ],
                [
                    'kode_jam' => $baris['kode_jam'],
                    'sks' => $baris['sks'],
                    'dosen_id' => $dosenId,
                    'ruang' => $baris['ruang'],
                    'semester' => $baris['semester'],
                ]
            );

            $dibuat++;
        }

        $this->command?->info("JadwalSeeder: {$dibuat} baris jadwal berhasil dibuat/diupdate.");

        if (!empty($dilewati)) {
            $this->command?->warn('JadwalSeeder: dosen berikut belum ada di tabel dosens, jadwalnya DILEWATI:');
            foreach ($dilewati as $nama => $jumlah) {
                $this->command?->warn("  - {$nama} ({$jumlah} jadwal)");
            }
        }
    }
